export const finnOvelse = (id: string) => {
  // Next kan levere parameteren URL-kodet (f.eks. «knebøy» → «kneb%C3%B8y»)
  let dekodet = id
  try { dekodet = decodeURIComponent(id) } catch {}
  return OVELSER.find(o => o.id === id || o.id === dekodet)
}

// ─── Muskler ────────────────────────────────────────────────────────────────
export type Muskel =
  | 'bryst' | 'skuldre' | 'trapes' | 'biceps' | 'triceps' | 'underarm'
  | 'mage' | 'skra' | 'lats' | 'ovreRygg' | 'korsrygg'
  | 'sete' | 'quads' | 'hamstrings' | 'adduktorer' | 'legger'

export const MUSKELNAVN: Record<Muskel, string> = {
  bryst: 'Bryst', skuldre: 'Skuldre', trapes: 'Trapes', biceps: 'Biceps', triceps: 'Triceps',
  underarm: 'Underarm', mage: 'Mage', skra: 'Skrå mage', lats: 'Latissimus', ovreRygg: 'Øvre rygg',
  korsrygg: 'Korsrygg', sete: 'Sete', quads: 'Forside lår', hamstrings: 'Bakside lår',
  adduktorer: 'Innside lår', legger: 'Legger',
}

const HELKROPP: Muskel[] = ['quads', 'sete', 'hamstrings', 'mage', 'skuldre', 'lats', 'bryst', 'triceps']

// Nøkkelord i fritekst → muskler. Rekkefølgen betyr noe: mer spesifikke først.
const REGLER: [RegExp, Muskel[]][] = [
  [/full kropp|hel kropp|hele kropp/i, HELKROPP],
  [/hel rygg/i, ['lats', 'ovreRygg', 'korsrygg']],
  [/posterior chain/i, ['hamstrings', 'sete', 'korsrygg']],
  [/indre lår|lår innside|adduk/i, ['adduktorer']],
  [/hofteabduk|setemusk|glute/i, ['sete']],
  [/pecs|bryst/i, ['bryst']],
  [/tricep/i, ['triceps']],
  [/bicep|brachialis/i, ['biceps']],
  [/brachioradialis|underarm/i, ['underarm']],
  [/bakre deltoid|rear delt|bakre skulder/i, ['skuldre', 'ovreRygg']],
  [/deltoid|skulder|skuldre|rotator/i, ['skuldre']],
  [/trapez|nakke/i, ['trapes']],
  [/lats|serratus/i, ['lats']],
  [/rhomboid|øvre.*rygg|midtre rygg|øvre bakre/i, ['ovreRygg']],
  [/erector|korsrygg|nedre rygg/i, ['korsrygg']],
  [/hamstring/i, ['hamstrings']],
  [/quad/i, ['quads']],
  [/gastrocnemius|soleus|legg/i, ['legger']],
  [/obliq|anti-rotasjon/i, ['skra']],
  [/rectus|mage|core|kjerne|transversus|hoftefleks/i, ['mage']],
  [/bein/i, ['quads', 'sete', 'hamstrings', 'legger']],
]

const fraTekst = (tekst: string): Muskel[] => {
  const ut: Muskel[] = []
  for (const [rx, m] of REGLER) if (rx.test(tekst)) for (const x of m) if (!ut.includes(x)) ut.push(x)
  return ut
}

const KATEGORI_FALLBACK: Record<string, Muskel[]> = {
  bryst: ['bryst'], rygg: ['lats', 'ovreRygg'], bein: ['quads', 'sete'], skuldre: ['skuldre'],
  bicep: ['biceps'], tricep: ['triceps'], core: ['mage'], fullkropp: HELKROPP,
  tabata: HELKROPP, cardio: ['quads', 'legger', 'hamstrings'], styrkeløft: HELKROPP,
  mobilitet: ['korsrygg', 'mage'], eksplosivitet: HELKROPP,
}

// Første ledd i muskelgruppe-teksten = primær, resten = sekundær
export function muskler(o: Pick<Ovelse, 'muskelgruppe' | 'kategori'>): { primaer: Muskel[]; sekundaer: Muskel[] } {
  const [forste, ...resten] = o.muskelgruppe.split(/,|\+/)
  let primaer = fraTekst(forste)
  if (!primaer.length) primaer = KATEGORI_FALLBACK[o.kategori] ?? []
  const sekundaer = fraTekst(resten.join(',')).filter(m => !primaer.includes(m))
  return { primaer, sekundaer }
}

// Hvilken side av kroppen viser muskelen best?
const BAKSIDE: Muskel[] = ['lats', 'ovreRygg', 'korsrygg', 'sete', 'hamstrings', 'triceps', 'trapes', 'legger']
export const visesBakfra = (m: Muskel[]) => m.filter(x => BAKSIDE.includes(x)).length > m.length / 2

// ─── Utstyr ─────────────────────────────────────────────────────────────────
export type UtstyrType = 'stang' | 'manualer' | 'kabel' | 'maskin' | 'kettlebell' | 'strikk' | 'kondisjon' | 'kroppsvekt'

export const UTSTYRNAVN: Record<UtstyrType, string> = {
  stang: 'Vektstang', manualer: 'Manualer', kabel: 'Kabel', maskin: 'Maskin',
  kettlebell: 'Kettlebell', strikk: 'Strikk', kondisjon: 'Kondisjon', kroppsvekt: 'Kroppsvekt',
}

export function utstyrType(o: Pick<Ovelse, 'utstyr' | 'kategori'>): UtstyrType {
  const u = o.utstyr.toLowerCase()
  if (/romaskin|sykkel|tredemølle|tau$|løpebane|trappemaskin|stair|boksesekk|elipse|airdyne|assault|battle/.test(u)) return 'kondisjon'
  if (/kabel/.test(u)) return 'kabel'
  if (/maskin/.test(u)) return 'maskin'
  if (/kettlebell/.test(u)) return 'kettlebell'
  if (/band|strikk/.test(u)) return 'strikk'
  if (/^(vektstang|ez-stang|stang)/.test(u)) return 'stang'
  if (/hantel|hantler/.test(u)) return 'manualer'
  if (/stang/.test(u) && !/pull-up|parallell/.test(u)) return 'stang'
  return o.kategori === 'cardio' ? 'kondisjon' : 'kroppsvekt'
}

// ─── Utvalg ─────────────────────────────────────────────────────────────────
// Felles for treningsgenerator, treningsøkt og kalenderforslag.
// Med frø blir utvalget likt hver gang (samme dato → samme forslag), uten frø tilfeldig.
function tilfeldig(fro: number) {
  let t = fro >>> 0
  return () => {
    t += 0x6d2b79f5
    let r = Math.imul(t ^ (t >>> 15), 1 | t)
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r)
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296
  }
}

const NIVA_RANG: Record<Vanskelighetsgrad, number> = { Nybegynner: 1, Middels: 2, Avansert: 3 }

// maksNiva: hopp over øvelser over brukerens nivå – men bare hvis det fortsatt er nok å velge mellom
export function utvalg(kategori: string, sted: Sted | 'alle', antall: number, fro?: number, maksNiva?: Vanskelighetsgrad): Ovelse[] {
  let pool = OVELSER.filter(o =>
    o.kategori === kategori && (sted === 'alle' || o.sted === sted || o.sted === 'begge'))
  if (maksNiva) {
    const passer = pool.filter(o => NIVA_RANG[o.vanskelighet] <= NIVA_RANG[maksNiva])
    if (passer.length >= Math.min(antall, pool.length)) pool = passer
  }
  const rng = fro === undefined ? Math.random : tilfeldig(fro)
  const a = [...pool]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]]
  }
  return a.slice(0, antall)
}

