const normaliser = (navn: string) => navn.toLowerCase().trim().replace(/\s+/g, ' ')

export const finnOvelseNavn = (navn: string) => {
  const n = normaliser(navn)
  const id = TIDLIGERE_NAVN[n]
  return OVELSER.find(o => o.navn.toLowerCase() === n) ?? (id ? OVELSER.find(o => o.id === id) : undefined)
}

// Alle navn en øvelse har vært lagret under (nåværende først) – til spørringer mot gamle logger
export const alleNavn = (navn: string): string[] => {
  const o = finnOvelseNavn(navn)
  if (!o) return [navn]
  const tidligere = Object.entries(TIDLIGERE_NAVN).filter(([, id]) => id === o.id)
    .map(([gammelt]) => OVELSER_ORIGINALNAVN[gammelt] ?? gammelt)
  return Array.from(new Set([o.navn, navn, ...tidligere]))
}

